    var url = (check && check.details_url) ? String(check.details_url) : '';
    var jobIdMatch = url.match(/\/jobs?\/(\d+)/);
    if (jobIdMatch) return fetchGithubJobLogsDetailed(jobIdMatch[1], scm, owner, repo);
    if (/\/actions\/runs\/\d+/.test(url)) {
