        return { reason: 'check-run log fetch failed: ' + fetchFailureDetail(e) };
    }
}

/** Fetch the raw GitHub job log for a check whose details_url contains /jobs/{id}. */
function fetchGithubCheckLogs(check, scm, owner, repo) {
